+package com.tripledger.expense;
+
+import java.math.BigDecimal;
+import lombok.RequiredArgsConstructor;
+import org.springframework.web.bind.annotation.*;
+
+@RestController
+@RequiredArgsConstructor
+public class ExpenseController {
+    private final ExpenseService service;
+
+    @PostMapping("/api/trips/{tripId}/expenses")
+    public CreatedResponse create(@PathVariable Long tripId, @RequestBody ExpenseRequest request) {
+        Expense saved = service.addExpense(tripId, request.memberId(), request.amount(), request.memo());
+        return new CreatedResponse(saved.getId());
+    }
+
+    public record ExpenseRequest(Long memberId, BigDecimal amount, String memo) {}
+    public record CreatedResponse(Long expenseId) {}
+}

