--- a/frontend/src/features/expense/ExpenseCreatePanel.tsx
+++ b/frontend/src/features/expense/ExpenseCreatePanel.tsx
@@ -1,2 +1,26 @@
-export function FeaturePanel() { return null; }
-// 화면 구현 예정
+import { useState } from 'react';
+import { api } from '../../lib/api';
+
+type Props = { tripId: number; memberId: number; reload: () => Promise<void> };
+
+export function ExpenseCreatePanel({ tripId, memberId, reload }: Props) {
+  const [amount, setAmount] = useState(45000);
+  const [memo, setMemo] = useState('');
+  const [error, setError] = useState('');
+  async function submit() {
+    setError('');
+    try {
+      await api.post(`/api/trips/${tripId}/expenses`, { memberId, amount, memo });
+      await reload();
+    } catch {
+      setError('요청을 처리하지 못했습니다. 잠시 후 다시 시도해주세요.');
+    }
+  }
+  return <section>
+    <h2>여행 지출 등록</h2>
+    <label>금액<input type="number" value={amount} onChange={e => setAmount(Number(e.target.value))} /></label>
+    <label>설명<input value={memo} onChange={e => setMemo(e.target.value)} /></label>
+    {error && <p role="alert">{error}</p>}
+    <button onClick={submit}>저장하기</button>
+  </section>;
+}

